#include <bits/stdc++.h>
using namespace std;

class Solution {public:string largestWordCount(vector<string>& messages,vector<string>& senders){unordered_map<string,int> cnt;string ans="";int best=0;for(int i=0;i<(int)messages.size();++i){int words=1;for(char c:messages[i])if(c==' ')++words;int cur=cnt[senders[i]]+=words;if(cur>best||(cur==best&&senders[i]>ans)){best=cur;ans=senders[i];}}return ans;} };
